AREA bss (RAM,REL)



;-----------------------------------------------
;  EQUATES
;-----------------------------------------------
bPOWERMASK:          equ   03h         ; Power field mask for CR3
LPF_CNUMMASK:        equ   1fh         ; Mask for A, B & C Caps
LPF_CFBMASK:         equ   80h         ; Mask for Feedback Caps
LPF_POLARITYMASK:    equ   20h         ; Mask of Asign field for CR0

LowpassSpectral_IfCond: equ LowpassSpectral_AMD_MSK & 0x01

IF (LowpassSpectral_AMD_VAL)
 IF (LowpassSpectral_IfCond)
  LowpassSpectral_AMD:  equ LowpassSpectral_AMD_VAL
 ELSE
  LowpassSpectral_AMD:  equ LowpassSpectral_AMD_VAL << 4
 ENDIF
ENDIF

AREA UserModules (ROM,REL)
;-----------------------------------------------------------------------------
;  FUNCTION NAME: LowpassSpectral_Start
;
;  DESCRIPTION: Applies power setting to the module's PSoC blocks
;
;-----------------------------------------------------------------------------
;
;  ARGUMENTS:    A register contains the power setting (constant)
;  RETURNS:      Nothing
;  SIDE EFFECTS: 
;    The A and X registers may be modified by this or future implementations
;    of this function.  The same is true for all RAM page pointer registers in
;    the Large Memory Model.  When necessary, it is the calling function's
;    responsibility to perserve their values across calls to fastcall16 
;    functions.
;

 LowpassSpectral_Start:
_LowpassSpectral_Start:
 LowpassSpectral_SetPower:
_LowpassSpectral_SetPower:
    RAM_PROLOGUE RAM_USE_CLASS_2
    and A, bPOWERMASK                        ; mask A to protect unchanged bits
    mov X, SP                                ; define temp store location

    push A                                   ; put power value in temp store

IF (LowpassSpectral_AMD_VAL)
   M8C_SetBank1
   mov   A, reg[LowpassSpectral_AMD_REG]         ; read modulator register
   and   A, ~LowpassSpectral_AMD_MSK             ; clear modulator bittfield in A
   or    A, LowpassSpectral_AMD                  ; combine modulator value with balance of register
   mov   reg[LowpassSpectral_AMD_REG], A         ; move complete value back to register
   M8C_SetBank0
ENDIF

    mov A, reg[LowpassSpectral_FLIN_CR3]    ; read power value
    and A, ~bPOWERMASK                       ; clear power bits in A
    or  A, [X]                               ; combine power value with balance of reg.
    mov reg[LowpassSpectral_FLIN_CR3], A    ; move complete value back to register

    mov A, reg[LowpassSpectral_FLOUT_CR3]   ; read power value
    and A, ~bPOWERMASK                       ; clear power bits in A
    or  A, [X]                               ; combine power value with balance of reg.
    mov reg[LowpassSpectral_FLOUT_CR3], A   ; move complete value back to register
    pop A
    RAM_EPILOGUE RAM_USE_CLASS_2
    ret

;-----------------------------------------------------------------------------
;  FUNCTION NAME: LowpassSpectral_SetCn, n=1..4
;
;  DESCRIPTION:   Alters the filter transfer function by modifying the value
;                 of the capacitors (defined in LowpassSpectral.inc)
;
;-----------------------------------------------------------------------------
;
;  ARGUMENTS:    The A register contains a non-negative integer less than 32
;  RETURNS:
;  SIDE EFFECTS: 
;    The A and X registers may be modified by this or future implementations
;    of this function.  The same is true for all RAM page pointer registers in
;    the Large Memory Model.  When necessary, it is the calling function's
;    responsibility to perserve their values across calls to fastcall16 
;    functions.
;

 LowpassSpectral_SetC1:
_LowpassSpectral_SetC1:
    RAM_PROLOGUE RAM_USE_CLASS_2
    and A, LPF_CNUMMASK                      ; mask A to protect unchanged bits
    mov X, SP                                ; define temp store location
    push A                                   ; put C1 value in temp store
    mov A, reg[LowpassSpectral_FILT_C1_REG] ; read current C1
    and A, ~LPF_CNUMMASK                     ; clear C1 bits in A
    or  A, [X]                               ; combine C1 value with balance of reg.
    mov reg[LowpassSpectral_FILT_C1_REG], A ; move complete value back to register
    pop  A
    RAM_EPILOGUE RAM_USE_CLASS_2
    ret

